void init_timer_BLINKY(void)
{
    RCC->APB2ENR &= ~RCC_APB2ENR_TIM11EN; // Limpiamos el reloj del timer TIM11
    RCC->APB2ENR |= RCC_APB2ENR_TIM11EN; // Habilitamos el reloj del timer TIM11

    TIM11->PSC = 16000 - 1; // Prescaler para obtener una frecuencia de 1 kHz (16 MHz / 16000 = 1 kHz)
    TIM11->ARR = 250 - 1; // Auto-reload para obtener un periodo de 500 ms (1 kHz / 500 = 2 Hz), cuando el contador llegue a 500, se levanta la bandera de interrupcion y se reinicia el contador a 0, es decir, se genera un desbordamiento.
    TIM11->CNT = 0; // Inicializamos el contador en 0

    TIM11->DIER |= TIM_DIER_UIE; // Habilitamos la interrupción por desbordamiento del temporizador TIM11
    TIM11->CR1 &= ~TIM_CR1_DIR; // Direccion ascendente
    TIM11->CR1 |= TIM_CR1_ARPE; // Habilitamos el auto-reload para que el contador se reinicie automaticamente cuando llegue al valor del auto-reload, es decir, cuando llegue a 500, se reinicia a 0.

    TIM11->SR &= ~TIM_SR_UIF; // Limpiamos la bandera de interrupción por desbordamiento
    /* TIM11 comparte la línea de interrupción del NVIC con TIM1 TRG/COM. */
    NVIC_EnableIRQ(TIM1_TRG_COM_TIM11_IRQn);
    TIM11->CR1 |= TIM_CR1_CEN; // Iniciamos el temporizador, es lo ultimo que se habilita
}

void TIM1_TRG_COM_TIM11_IRQHandler(void)
{
    if (TIM11->SR & TIM_SR_UIF) // Verificamos si la bandera esta subida, es decir si lainterrupción fue generada por el desbordamiento del temporizador TIM11
    {
        TIM11->SR &= ~TIM_SR_UIF; // Bajamos la bandera. Limpiamos la bandera de interrupción por desbordamiento
        GPIOH->ODR ^= GPIO_ODR_OD1; // Conmutamos PH1, donde está conectado el Blinky de la tarjeta didáctica.
    }
}
